using System;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Collections.Concurrent;
using System.Runtime.InteropServices;

namespace ImagePipeline
{
    public enum CircuitState { Closed, Open, HalfOpen }

    public class CircuitBreaker
    {
        private volatile CircuitState _state = CircuitState.Closed;
        private int _failureCount = 0;
        private readonly int _threshold = 3;
        private DateTime _lastFailureTime;
        private readonly TimeSpan _recoveryTimeout = TimeSpan.FromSeconds(30);
        private readonly object _syncRoot = new object();

        public CircuitState State => _state;

        public bool AllowRequest()
        {
            if (_state == CircuitState.Closed) return true;
            if (_state == CircuitState.Open)
            {
                if (DateTime.UtcNow - _lastFailureTime > _recoveryTimeout)
                {
                    _state = CircuitState.HalfOpen;
                    return true;
                }
                return false;
            }
            return true; // HalfOpen allows one request
        }

        public void RecordSuccess()
        {
            lock (_syncRoot)
            {
                _failureCount = 0;
                _state = CircuitState.Closed;
            }
        }

        public void RecordFailure()
        {
            lock (_syncRoot)
            {
                _failureCount++;
                _lastFailureTime = DateTime.UtcNow;
                if (_failureCount >= _threshold)
                    _state = CircuitState.Open;
            }
        }
    }

    public class ImageBuffer : IDisposable
    {
        private IntPtr _nativeBuffer;
        private int _size;
        private volatile int _disposed = 0;
        private GCHandle _pinHandle;
        private byte[] _managedBuffer;
        private readonly object _accessLock = new object();

        public IntPtr NativePointer => _nativeBuffer;
        public int Size => _size;

        public ImageBuffer(int width, int height, int channels)
        {
            _size = width * height * channels;
            _managedBuffer = new byte[_size];
            _pinHandle = GCHandle.Alloc(_managedBuffer, GCHandleType.Pinned);
            _nativeBuffer = _pinHandle.AddrOfPinnedObject();
        }

        public void WritePixelData(byte[] source, int offset, int count)
        {
            if (source == null) throw new ArgumentNullException(nameof(source));
            if (offset < 0) throw new ArgumentOutOfRangeException(nameof(offset));
            if (count < 0) throw new ArgumentOutOfRangeException(nameof(count));
            if (offset > source.Length - count)
                throw new ArgumentException("offset and count exceed the bounds of the source array.");

            lock (_accessLock)
            {
                if (_disposed == 1) throw new ObjectDisposedException(nameof(ImageBuffer));
                if (count > _size)
                    throw new ArgumentException("count exceeds the size of the destination buffer.", nameof(count));
                Marshal.Copy(source, offset, _nativeBuffer, count);
            }
        }

        public byte[] ReadPixelData()
        {
            lock (_accessLock)
            {
                if (_disposed == 1) throw new ObjectDisposedException(nameof(ImageBuffer));
                byte[] result = new byte[_size];
                Marshal.Copy(_nativeBuffer, result, 0, _size);
                return result;
            }
        }

        public void Dispose()
        {
            lock (_accessLock)
            {
                if (Interlocked.CompareExchange(ref _disposed, 1, 0) == 0)
                {
                    _pinHandle.Free();
                    _nativeBuffer = IntPtr.Zero;
                    _managedBuffer = null;
                }
            }
        }
    }

    public class PipelineStage
    {
        private readonly Func<ImageBuffer, ImageBuffer> _transform;
        private readonly CircuitBreaker _breaker;
        private readonly string _name;

        public PipelineStage(string name, Func<ImageBuffer, ImageBuffer> transform, CircuitBreaker breaker)
        {
            _name = name;
            _transform = transform;
            _breaker = breaker;
        }

        public async Task<ImageBuffer> ExecuteAsync(ImageBuffer input, CancellationToken ct)
        {
            if (!_breaker.AllowRequest())
                throw new InvalidOperationException($"Circuit open for stage: {_name}");

            try
            {
                var result = await Task.Run(() => _transform(input), ct);
                _breaker.RecordSuccess();
                return result;
            }
            catch (Exception)
            {
                _breaker.RecordFailure();
                throw;
            }
        }
    }

    public class ImageProcessingPipeline : IDisposable
    {
        private readonly ConcurrentQueue<ImageBuffer> _bufferPool = new();
        private readonly List<PipelineStage> _stages = new();
        private readonly CancellationTokenSource _cts = new();
        private volatile int _shuttingDown = 0;
        private readonly ManualResetEventSlim _shutdownEvent = new(false);
        private int _activeOperations = 0;

        public ImageProcessingPipeline()
        {
            AppDomain.CurrentDomain.ProcessExit += OnProcessExit;
            Console.CancelKeyPress += OnCancelKeyPress;
        }

        public void AddStage(string name, Func<ImageBuffer, ImageBuffer> transform)
        {
            _stages.Add(new PipelineStage(name, transform, new CircuitBreaker()));
        }

        private void OnProcessExit(object sender, EventArgs e)
        {
            InitiateShutdown();
        }

        private void OnCancelKeyPress(object sender, ConsoleCancelEventArgs e)
        {
            e.Cancel = true;
            InitiateShutdown();
        }

        private void InitiateShutdown()
        {
            if (Interlocked.CompareExchange(ref _shuttingDown, 1, 0) == 0)
            {
                _cts.Cancel();
                // Wait for active operations to complete before draining
                SpinWait.SpinUntil(() => Volatile.Read(ref _activeOperations) == 0, TimeSpan.FromSeconds(5));
                DrainBufferPool();
                _shutdownEvent.Set();
            }
        }

        private void DrainBufferPool()
        {
            while (_bufferPool.TryDequeue(out var buffer))
            {
                buffer.Dispose();
            }
        }

        public ImageBuffer AcquireBuffer(int width, int height, int channels)
        {
            if (_bufferPool.TryDequeue(out var buffer))
                return buffer;
            return new ImageBuffer(width, height, channels);
        }

        public void ReturnBuffer(ImageBuffer buffer)
        {
            if (_shuttingDown == 1)
            {
                buffer.Dispose();
                return;
            }
            _bufferPool.Enqueue(buffer);
        }

        public async Task<byte[]> ProcessImageAsync(byte[] rawPixels, int width, int height, int channels)
        {
            Interlocked.Increment(ref _activeOperations);
            try
            {
                if (_shuttingDown == 1)
                    return Array.Empty<byte>();

                var buffer = AcquireBuffer(width, height, channels);
                try
                {
                    buffer.WritePixelData(rawPixels, 0, rawPixels.Length);

                    ImageBuffer current = buffer;
                    foreach (var stage in _stages)
                    {
                        var next = await stage.ExecuteAsync(current, _cts.Token);
                        if (next != current && current != buffer)
                            ReturnBuffer(current);
                        current = next;
                    }

                    var result = current.ReadPixelData();
                    ReturnBuffer(current);
                    return result;
                }
                catch (OperationCanceledException)
                {
                    buffer.Dispose();
                    return Array.Empty<byte>();
                }
            }
            finally
            {
                Interlocked.Decrement(ref _activeOperations);
            }
        }

        public void Dispose()
        {
            InitiateShutdown();
            _shutdownEvent.Dispose();
            _cts.Dispose();
            AppDomain.CurrentDomain.ProcessExit -= OnProcessExit;
            Console.CancelKeyPress -= OnCancelKeyPress;
        }
    }

    public class Program
    {
        public static async Task Main(string[] args)
        {
            using var pipeline = new ImageProcessingPipeline();

            pipeline.AddStage("Grayscale", buffer =>
            {
                var pixels = buffer.ReadPixelData();
                var output = new ImageBuffer(256, 256, 1);
                for (int i = 0; i < pixels.Length; i += 3)
                {
                    byte gray = (byte)(pixels[i] * 0.299 + pixels[i + 1] * 0.587 + pixels[i + 2] * 0.114);
                    output.WritePixelData(new[] { gray }, 0, 1);
                }
                return output;
            });

            pipeline.AddStage("Threshold", buffer =>
            {
                var pixels = buffer.ReadPixelData();
                for (int i = 0; i < pixels.Length; i++)
                    pixels[i] = pixels[i] > 128 ? (byte)255 : (byte)0;
                var output = new ImageBuffer(256, 256, 1);
                output.WritePixelData(pixels, 0, pixels.Length);
                return output;
            });

            var testImage = new byte[256 * 256 * 3];
            new Random(42).NextBytes(testImage);

            var result = await pipeline.ProcessImageAsync(testImage, 256, 256, 3);
            Console.WriteLine($"Processed {result.Length} bytes");
        }
    }
}
